import{_ as a,o as n,c as p,a3 as t}from"./chunks/framework.Dz5Q8p4s.js";const o=JSON.parse('{"title":"FlowWAM: Optical Flow as a Unified Action Representation for World Action Models","description":"","frontmatter":{"title":"FlowWAM: Optical Flow as a Unified Action Representation for World Action Models","arxiv":"2607.13017","date":"2026-07-14","authors":"Yixiang Chen, Peiyan Li, Yuan Xu, Qisen Ma, Jiabing Yang, Kai Wang, Jianhua Yang, Dong An, He Guan, et al.","categories":"cs.RO, cs.CV","topics":"视频生成赋能具身智能, 光流动作表示, 世界动作模型","outline":[2,2]},"headers":[],"relativePath":"papers/2607.13017.md","filePath":"papers/2607.13017.md","lastUpdated":null}'),l={name:"papers/2607.13017.md"};function e(m,s,i,r,c,h){return n(),p("div",null,[...s[0]||(s[0]=[t('<h1 id="flowwam-optical-flow-as-a-unified-action-representation-for-world-action-models" tabindex="-1">FlowWAM: Optical Flow as a Unified Action Representation for World Action Models <a class="header-anchor" href="#flowwam-optical-flow-as-a-unified-action-representation-for-world-action-models" aria-label="Permalink to &quot;FlowWAM: Optical Flow as a Unified Action Representation for World Action Models&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2607.13017" target="_blank" rel="noreferrer">2607.13017</a></td></tr><tr><td><strong>提交日期</strong></td><td>2026-07-14</td></tr><tr><td><strong>作者</strong></td><td>Yixiang Chen, Peiyan Li, Yuan Xu, Qisen Ma, Jiabing Yang, Kai Wang, Jianhua Yang, Dong An, He Guan, et al.（中科院自动化所 NLPR / 国科大 / FiveAges / MBZUAI / 阿里）</td></tr><tr><td><strong>分类</strong></td><td>cs.RO, cs.CV</td></tr><tr><td><strong>一句话</strong></td><td>把动作编成 HSV 色轮的稠密光流视频，让它与 RGB 共用同一个预训练视频生成器的 VAE 与 transformer——生成流即策略，给定流即世界模型。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/video-for-embodied-ai">视频生成赋能具身智能</a></p></blockquote><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>World Action Model 的卖点是复用预训练视频生成器里的运动与时序先验。但要把这些先验用于控制，必须先回答一个表示问题：动作应该长什么样，才能既贴合视频生成器的输入格式，又携带足够的运动线索被解码成可执行控制？</p><p>现有答案都在一端妥协。数值动作 token 精确但属于另一个模态，不同机器人的动作空间还互不通约；学出来的 latent action 摆脱了本体依赖却抽象，未必保留控制所需的稠密空间线索；最近的图像空间动作（ray map、embodiment mask、多视角动作图）把控制信号画进视觉域，但它们本质是静态空间提示，说的是&quot;动作发生在哪里&quot;，不说&quot;可见的每一部分如何跨帧移动&quot;。作者的判断是：这些仍是逐帧注入生成器的条件，不是随预测视频一起演化的时序稠密动作表示。</p><p>这个缺口值得填，因为操作任务的成败往往不取决于位置而取决于运动本身——同一个抓取点、不同的接近方向与速度，结果完全不同。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p><strong>WAM 主线</strong>分两支。一支在共享生成过程里同时出视频与动作：DreamZero、Cosmos Policy 用动作 token 微调视频生成器，UWM、CoVAR 让视频与动作两个扩散头共享 latent。另一支走 generate-then-infer：先生成未来视频，再用逆动力学模型或因果预测模块反推动作。两支都证明了视频先验对控制有价值，但动作始终是一条异质流，必须靠动作专属的 token、头或解码器与视频 latent 缝合。</p><p><strong>光流在操作里的用法</strong>已有不少，但位置都不同。一类把流当辅助监督或运动目标挂在 VLA 上；一类把它当模块间的中间变量（flow-to-action、规划、未来流预测）；LangToMo、DAWN 用结构化像素运动桥接高层运动生成与底层控制；ATM 建模稀疏点轨迹。作者的批评很准确：这些工作把流<strong>留在视频生成器之外</strong>，当作辅助目标、规划变量或模块桥梁，从没把它当成生成器内部的一条原生流。</p><p>真正没被做的是：让流与 RGB 共用同一个 VAE、同一批 transformer 权重，从而使&quot;预测动作&quot;和&quot;预测视频&quot;在数学上是同一件事。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>起点是一个格式观察。预训练视频生成器吃的是 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7667em;vertical-align:-0.0833em;"></span><span class="mord mathnormal" style="margin-right:0.0813em;">H</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.7667em;vertical-align:-0.0833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">W</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">3</span></span></span></span> 的图像序列，它的 VAE、patch embedding、RoPE、注意力结构全部围绕这个格式优化。任何不是这个格式的东西进来，都要新加一条通路，而新通路的参数是随机初始化的，先验用不上。</p><p>第二个观察来自光流的经典可视化：HSV 色轮把方向映成色相、幅值映成饱和度，得到的就是一张 RGB 图。这个映射在给定归一化常数下是可逆的。于是一个诱人的巧合出现了——稠密位移场天然能被写成视频格式，且不损失信息。</p><p>第三步是问：如果流就是视频，那两个模式就只是&quot;流是未知量还是已知量&quot;的区别。未知就一起去噪，模型在预测运动计划，这是策略；已知就固定住只去噪 RGB，模型在按指定运动渲染未来，这是世界模型。同一套权重，两种用法，不需要任何额外设计。</p><p>第四步是可扩展性。既然流能从任意原始视频里抽出来，不需要动作标签，那么无标注的人类第一人称视频也可以直接参与训练——这补上了 WAM 路线一直缺的&quot;动作无关预训练&quot;通道。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>动作与视频之间的鸿沟不是语义的而是格式的。把稠密位移场用色轮编成 RGB，动作就变成了视频生成器眼里的另一段视频，可以共用 VAE、共用 transformer、共用注意力。此后&quot;预测动作&quot;与&quot;预测未来&quot;是同一个去噪过程的两条并行流，谁被观测谁就是条件。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>底座 Wan2.2-TI2V-5B，VAE 与 UMT5-XXL 文本编码器冻结。以 RoboTwin 2.0 的 Handover Mic 为例：</p><ul><li><strong>流编码</strong>：<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">F</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">ϕ</span><span class="mopen">(</span><span class="mord"><span class="mord mathbf" style="margin-right:0.109em;">f</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.109em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span>，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord text"><span class="mord">H</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.355em;vertical-align:-0.345em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.01em;"><span style="top:-2.655em;"><span class="pstrut" style="height:3em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">2</span><span class="mord mathnormal mtight" style="margin-right:0.0359em;">π</span></span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.485em;"><span class="pstrut" style="height:3em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mop mtight"><span class="mord mathrm mtight">atan2</span></span><span class="mopen mtight">(</span><span class="mord mathnormal mtight" style="margin-right:0.0359em;">v</span><span class="mpunct mtight">,</span><span class="mord mathnormal mtight">u</span><span class="mclose mtight">)</span><span class="mbin mtight">+</span><span class="mord mathnormal mtight" style="margin-right:0.0359em;">π</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.345em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span></span></span></span>，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord text"><span class="mord">S</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">∥</span><span class="mord"><span class="mord mathbf" style="margin-right:0.109em;">f</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.109em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mord">∥/</span><span class="mord mathnormal">m</span></span></span></span>，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord text"><span class="mord">V</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">1</span></span></span></span>。幅值上限 25 px，小于 0.5 px 的位移置零去噪。</li><li><strong>双流架构</strong>：RGB 与流各自过同一个冻结 VAE；<strong>流特有的参数只有 patch embedding 与输出头</strong>（由 RGB 对应层深拷贝初始化），全部 transformer block 共享；自注意力内两流 token 拼接做联合注意力再拆回，RoPE 各自独立施加。</li><li><strong>两种模式</strong>：两流首帧 latent 都固定为参考观测的干净编码。策略模式下其余帧全从高斯噪声联合去噪；世界模型模式下流 latent 被设为目标运动的干净编码并全程固定，只去噪 RGB。</li><li><strong>动作专家</strong>：30 层 / 1024 隐藏维 / 约 780M 参数的 transformer，交叉注意到双流 DiT 的逐层隐状态，条件于当前本体状态，用 flow matching 预测 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">N</span></span></span></span> 步动作 chunk（动作维 14，32 步）。为消除训练/推理分布差，有 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">p</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.5</span></span></span></span> 的训练步把 latent 按 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6813em;"></span><span class="mord accent"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6813em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathbf">z</span></span><span style="top:-3.3634em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.25em;"><span class="mord">~</span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord">1</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">σ</span><span class="mclose">)</span><span class="mord mathbf">z</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.4444em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">σ</span><span class="mord"><span class="mord"><span class="mord boldsymbol">ϵ</span></span></span></span></span></span>、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">σ</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∼</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathcal" style="margin-right:0.0993em;">U</span><span class="mopen">[</span><span class="mord">0</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">1</span><span class="mclose">]</span></span></span></span> 加噪后再喂，并把 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">σ</span></span></span></span> 作为辅助嵌入告诉动作专家。</li><li><strong>两阶段训练</strong>：Stage 1 只在 EgoDex 上按 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathcal">L</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">video</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 训双流 DiT（无动作标签，30→15 fps，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">320</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">256</span></span></span></span>，帧桶 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">{</span><span class="mord">17</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">33</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">49</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">65</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">81</span><span class="mclose">}</span></span></span></span>）；Stage 2 接上动作专家在 RoboTwin 2.0 上联合优化。32 张 H100。</li><li><strong>多视角</strong>：头部与左右腕视角按 T 形拼成 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">320</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">384</span></span></span></span> 单帧，<strong>流监督只加在头部区域，两个腕视角的流区域填常量占位符</strong>。</li></ul><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>三处形式化各自承担一个论证。</p><p><strong>可逆性。</strong> 在给定幅值归一化常数 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">m</span></span></span></span> 下，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">ϕ</span></span></span></span> 是双射，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.0641em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathnormal">ϕ</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">−</span><span class="mord mtight">1</span></span></span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">F</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span> 能恢复数值流场。这一条是全部叙事的地基：如果编码有损，那么&quot;流是动作表示&quot;就退化成&quot;流是动作的有损提示&quot;，policy 模式解出的动作就没有理由准确。实践上 25 px 截断与 0.5 px 阈值都破坏了严格可逆性，作者未讨论这个张力。</p><p><strong>双流 flow matching。</strong> 两流共享同一时间步 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6151em;"></span><span class="mord mathnormal">t</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∼</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathcal" style="margin-right:0.0993em;">U</span><span class="mopen">[</span><span class="mord">0</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">1</span><span class="mclose">]</span></span></span></span>，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5944em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathbf">z</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord">1</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">t</span><span class="mclose">)</span><span class="mord"><span class="mord mathbf">z</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6151em;"></span><span class="mord mathnormal">t</span><span class="mord"><span class="mord"><span class="mord boldsymbol">ϵ</span></span></span></span></span></span>，损失</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathcal">L</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">video</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord">1</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1.0361em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal">λ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.1076em;">f</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mclose">)</span><span class="mord"><span class="mord mathcal">L</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">RGB</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.9805em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal">λ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.1076em;">f</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mord"><span class="mord mathcal">L</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">flow</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:2em;"></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathcal">L</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathcal">L</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">video</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.8444em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">λ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">a</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mord"><span class="mord mathcal">L</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3175em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">action</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span></span></p><p>共享时间步是关键细节：如果两流各自采样 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6151em;"></span><span class="mord mathnormal">t</span></span></span></span>，则在世界模型模式下（流为干净、RGB 为噪声）出现的输入组合在训练中从未见过。共享 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6151em;"></span><span class="mord mathnormal">t</span></span></span></span> 保证了两流噪声水平始终一致，代价是模型从未学过&quot;一流干净一流带噪&quot;的配置——而这恰恰是世界模型模式的推理配置。作者用首帧替换与条件帧加噪部分缓解，但两者并不等价。</p><p><strong>运动重加权。</strong> 操作场景的流在空间上极稀疏，运动集中在本体与接触区。若不加权，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathcal">L</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">flow</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 会被静止背景主导：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0269em;">w</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3175em;"><span style="top:-2.55em;margin-left:-0.0269em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">motion</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">1</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.4445em;"></span><span class="mord mathnormal" style="margin-right:0.0037em;">α</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">⋅</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:2.8166em;vertical-align:-1.1583em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.6583em;"><span style="top:-2.143em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mop">max</span><span class="mopen">⟨</span><span class="mord">∣</span><span class="mord"><span class="mord mathbf">z</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.7751em;"><span style="top:-2.989em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.1076em;">f</span></span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord"><span class="mord mathbf">z</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.967em;"><span style="top:-2.3987em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">ref</span></span></span></span></span><span style="top:-3.1809em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.1076em;">f</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.3013em;"><span></span></span></span></span></span></span><span class="mord">∣</span><span class="mclose"><span class="mclose">⟩</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">c</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.6913em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mopen">⟨</span><span class="mord">∣</span><span class="mord"><span class="mord mathbf">z</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8491em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.1076em;">f</span></span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord"><span class="mord mathbf">z</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.967em;"><span style="top:-2.3987em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">ref</span></span></span></span></span><span style="top:-3.1809em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.1076em;">f</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.3013em;"><span></span></span></span></span></span></span><span class="mord">∣</span><span class="mclose"><span class="mclose">⟩</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">c</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:1.1583em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span></span></span></span></span></p><p>即按 latent 相对参考帧的通道平均偏差归一化后加权。消融显示去掉它成功率从 89.8 掉到 83.9，是策略侧四项消融里落差最小的一项（去掉动作专家的随机 latent 条件掉到 82.1，换成数值动作掉到 69.8）。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>策略模式（RoboTwin 2.0，50 个双臂任务，Clean 50 条 + Random 500 条演示，每任务 100 次 rollout）</strong>：FlowWAM 92.94 / 92.14，领先所有 VLA 与 WAM 基线。但要看清余量：Fast-WAM 是 91.88 / 91.78，差距只有 <strong>+1.06 / +0.36</strong>；X-WAM 89.76 / 90.68。</p><p>消融口径的问题更大。<strong>FlowWAM w/o 预训练只有 82.40 / 80.80，低于表 1 里每一个 WAM 基线</strong>（Motus 88.66/87.02、GigaWorld-Policy 86.36/85.04、X-WAM、Fast-WAM）。正文写&quot;即使没有 ego 视频预训练 FlowWAM 也已超过 VLA 基线，说明流本身贡献了主要增益、预训练只是放大器&quot;——前半句对（VLA 基线是 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">0.5</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 42.98 与 X-VLA 72.88），后半句与数字相反：预训练带来 +10.54 / +11.34，而无预训练时该方法在 WAM 阵营里垫底。正文还称预训练增益&quot;在 Random 上明显更大&quot;，实际是 +11.34 对 +10.54，差 0.8 点。</p><p><strong>世界模型模式（WorldArena，121 帧 rollout @24 fps，16 项指标算术平均得 EWMScore）</strong>：FlowWAM 63.71 居首，但相对 ABot-PhysWorld 62.63 与 GigaWorld-1 62.34 只高约 1.1–1.4。真正拉开差距的是 Trajectory Accuracy 64.26 对 GigaWorld-1 的 54.27（+9.99，相对 18.4%），以及 Depth Accuracy 98.97。代价侧同样清楚：Subject Consistency 82.46 低于 Ctrl-World 的 83.56，Background Consistency 89.97 低于 Ctrl-World 的 90.30。</p><p><strong>真机（7 个任务，两个平台，每任务 100 条演示、10 次试验）</strong>：FlowWAM 均值 75.7%，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">0.5</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 61.4%，Motus 57.1%，双臂任务上差距更大。仅有柱状图，无数值表。</p><p><strong>可解码性（图 4c）</strong>：50 个 RoboTwin 任务上，预测流与 RAFT 伪真值流的误差与成功率呈 Pearson <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">−</span><span class="mord">0.81</span></span></span></span>。作者用它论证增益来自流预测本身而非解码器捷径。</p><p><strong>消融</strong>：策略侧把流换成数值动作掉到 69.8，换成原始 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord mathnormal">u</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">v</span><span class="mclose">)</span></span></span></span> 张量掉到 72.3；世界模型侧只换条件输入，text-only 49.31 → 数值动作 54.18 → 原始 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord mathnormal">u</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">v</span><span class="mclose">)</span></span></span></span> 56.72 → 图像动作（mask）57.84 → 完整 RGB 流 65.23。注意消融里的完整模型是 89.8（策略）与 65.23（世界模型），与主表的 92.94 与 63.71 都对不上；后者作者用&quot;官方评测需远程提交、改用自建验证划分&quot;解释，<strong>前者没有任何解释</strong>。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句话</strong>：光流经 HSV 色轮编码后与 RGB 同格式，因而能共用预训练视频生成器的 VAE 与全部 transformer 权重，只留 patch embedding 与输出头两处流特有参数。生成流即策略、给定流即世界模型，两种模式只差&quot;流是否被观测&quot;。流可从无动作标签的第一人称视频中抽取，打开了动作无关预训练通道。RoboTwin 2.0 上 92.94/92.14，WorldArena EWMScore 63.71，最大优势集中在轨迹准确度而非外观类指标。策略侧的绝大部分增益实际来自 EgoDex 预训练，去掉后落到 WAM 阵营末位。</p><p><strong>3 句话</strong>：动作与视频之间的鸿沟主要是格式的，色轮编码就能抹平。同一套权重据此同时充当策略与世界模型，条件方向可逆。轨迹跟随大幅领先，外观一致性略输，整体分只领先约一分。</p><p><strong>1 句话</strong>：把动作画成一段光流视频，视频生成器就不需要学一门新语言。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最要害的一条：<strong>用于监督与条件化的&quot;光流&quot;确实是从视频里抽出的环境运动</strong>。整篇论文的可扩展性论证（&quot;流可以从原始视频里轻松抽取，无需动作标签&quot;）与可靠性论证（&quot;稠密逐像素位移场&quot;）都建立在这上面。</p><p>附录 A.3 推翻了它在机器人侧的成立。RoboTwin 的流目标不是对观测视频跑 RAFT 得到的，而是<strong>把录制的关节动作在 SAPIEN 里用机器人 URDF 回放、把运动本体渲染到静态背景上、再对这些&quot;只有机器人&quot;的帧跑 RAFT</strong>。这意味着三件事同时发生：其一，产生流目标需要动作标签加上仿真器加上 URDF，恰恰是&quot;无需动作标签&quot;所要避免的全部东西；其二，流里<strong>完全不含物体运动、光照变化与背景运动</strong>，所谓&quot;稠密环境位移场&quot;在机器人阶段实为&quot;本体运动的可微渲染&quot;；其三，既然流是从动作确定性渲染出来的，那么&quot;从流解码动作&quot;在信息论上接近一个逆渲染问题，而不是从观测中推断动作。</p><p>于是本文对图像空间动作（ray map、mask、多视角动作图）的批评在很大程度上回到了自己身上——那些方法也是把动作渲染进图像域，区别只在于渲染的是位置还是位移。作者的辩护应当是&quot;位移比位置携带更多信息&quot;，而这恰好被消融支持（mask 57.84 vs 流 65.23），但&quot;可从无标注视频扩展&quot;这一条只对 EgoDex 预训练阶段成立，对机器人训练与部署阶段不成立。</p><p>叠加的次级问题：三个视角里有两个（左右腕）的流区域是常量占位符，因此&quot;稠密&quot;实际只覆盖头部视角。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>一周内可做，目标是把&quot;流表示&quot;与&quot;EgoDex 预训练&quot;两个因素分开——这是全文归因中最含糊的一处。</p><p>在 RoboTwin 2.0 的一个 10 任务子集上训四个模型，其余全部固定（同骨干、同步数、同 batch、同评测的 100 次 rollout）：</p><ul><li><strong>A</strong>：数值动作 token，无预训练。</li><li><strong>B</strong>：数值动作 token，<strong>在 EgoDex 上按纯 RGB 视频目标预训练</strong>（去掉流流）。</li><li><strong>C</strong>：流表示，无预训练。</li><li><strong>D</strong>：流表示 + EgoDex 双流预训练（即完整 FlowWAM）。</li></ul><p>判据：若 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7667em;vertical-align:-0.0833em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">D</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0715em;">C</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.7667em;vertical-align:-0.0833em;"></span><span class="mord mathnormal" style="margin-right:0.0502em;">B</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal">A</span></span></span></span>，说明预训练的收益与动作表示无关，流的净贡献就是 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7667em;vertical-align:-0.0833em;"></span><span class="mord mathnormal" style="margin-right:0.0715em;">C</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal">A</span></span></span></span>（本文口径下约 20 点，但 C 仍低于 WAM 基线）；若 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7667em;vertical-align:-0.0833em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">D</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.7224em;vertical-align:-0.0391em;"></span><span class="mord mathnormal" style="margin-right:0.0715em;">C</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≫</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.7667em;vertical-align:-0.0833em;"></span><span class="mord mathnormal" style="margin-right:0.0502em;">B</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal">A</span></span></span></span>，则流与流预训练存在协同，本文&quot;流是主要因素&quot;的表述可以被修正为&quot;流预训练是主要因素&quot;。这个实验只需四次训练，10 任务子集可把成本压到单机 8 卡数天内。</p><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>最有力的攻击针对世界模型模式：<strong>论文从未说明 WorldArena 评测里作为条件的目标流从何而来</strong>。WorldArena 给的是初始帧、语言指令与录制的关节动作轨迹；FlowWAM 需要的是流视频。若沿用附录 A.3 的做法（URDF 回放渲染），则这是合法的，但需要每个数据集的机器人模型与相机标定，且全文对 WorldArena 侧的训练数据、训练步数、流生成方式<strong>只字未提</strong>——§4.2 只有 setup 与 results，没有对应的实现小节。若流是对参考真值视频跑 RAFT 得到的，则 Trajectory Accuracy 64.26 与 Depth Accuracy 98.97 就带有直接的真值泄漏（TA 的算法是用 SAM3 抽机械臂框再与参考轨迹做 NDTW 对齐——如果条件流本身来自参考视频，这个指标接近自我比对）。这两种可能性无法从论文中区分，而它们对结论的含义截然相反。</p><p>第二条攻击针对跨论文的基线可比性。同期的 <a href="/notes/papers/2607.04988">InternVLA-A1.5</a> 在同样的 RoboTwin 2.0 协议下报告 Motus 88.7/87.0 与 Fast-WAM 91.9/91.8，与本文的 88.66/87.02 与 91.88/91.78 几乎逐位相同，<strong>唯独 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">0.5</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 一行相差 33～40 个百分点</strong>（本文 42.98/43.84，对方 82.7/76.8）。同一个基线在两篇同周论文里差这么多，说明其实现或超参存在重大差异；本文正文用&quot;FlowWAM 无预训练版已超过 VLA 基线&quot;来论证流表示的价值，而这个论证的强度完全取决于那个 42.98。若采用对方的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">0.5</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 数值，FlowWAM w/o PT 的 82.40 反而低于 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">0.5</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>。</p><p>第三条：可解码性的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">−</span><span class="mord">0.81</span></span></span></span> 是在<strong>任务层面</strong>（50 个点）算的，而任务难度会同时推高流误差与降低成功率，这本身就足以产生强负相关，不能单独支持&quot;策略增益追随流预测质量&quot;。要排除混杂需要的是<strong>同一任务内</strong>跨 checkpoint 或跨随机种子的相关，论文没有做。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>驱动局限</strong>：当前的流是<strong>本体运动的渲染</strong>，物体、流体与形变的运动被显式剔除；这让表示很干净，但也让世界模型模式退化为&quot;按指定机械臂运动重绘场景&quot;，对交互后果的预测能力没有被真正检验。同时两流共享时间步，模型从未在训练中见过&quot;一流干净一流带噪&quot;的配置，而那正是世界模型模式的推理配置。</p><p><strong>新 framing</strong>：把流从&quot;动作的渲染&quot;改成&quot;因果的分解&quot;——显式拆成<strong>本体流</strong>与<strong>物体流</strong>两条子流，前者由动作决定（可从 URDF 渲染），后者必须由模型预测。这样世界模型模式就有了真正的预测负担：给定本体流，物体流是模型对物理后果的显式承诺，可以直接与 RAFT 抽出的真实物体流比对。策略模式则反过来：先预测物体流（想要的后果），再反解本体流（该怎么动），这是一个天然的目标条件规划接口。</p><p><strong>可借鉴的相邻工具</strong>：视频分解与分层运动表示（layered motion / object-centric decomposition）提供了把光流拆成前景-背景分量的成熟做法；可控图像编辑里的分支条件调度提供了&quot;部分条件干净、部分条件带噪&quot;的训练配方，正好补上共享时间步留下的训练-推理错配。</p><p><strong>第一个实验</strong>：在 RoboTwin 2.0 上把流通道从 3 维扩到 6 维（本体流 + 物体流各一张 HSV 图），物体流用观测视频减去本体回放渲染后跑 RAFT 得到；训练时对两条子流采样独立的时间步。评测两件事：(a) 世界模型模式下，只给本体流、让模型预测物体流，与 RAFT 真值的端点误差；(b) 策略模式下，给定目标物体流反解动作的成功率。判据是 (a) 是否显著优于&quot;直接从 RGB 预测未来帧再抽流&quot;这一朴素基线——若不是，则说明当前所有 WAM 的物体动力学预测能力尚未超过像素级重建，这本身就是一个值得报告的负结果。</p>',60)])])}const d=a(l,[["render",e]]);export{o as __pageData,d as default};
